#!/bin/bash
set -e

# NoFutureWeather 下 PatchMLPAllFeatures 的随机时间 token 热身与 DBLoss 长度预测；5min一个模型点。
ROOT="$(cd "$(dirname "$0")/../../../.." && pwd)"
cd "$ROOT"
export PYTHONUNBUFFERED=1
export CUDA_VISIBLE_DEVICES=0
unset LD_LIBRARY_PATH

POINT_INTERVAL_SECONDS=300
DATASET_NAME=GuangningWindPower5min
RUN_ROOT=".runs/WeatherComparison/NoFutureWeather/PatchMLPAllFeatures/DBLoss/$DATASET_NAME/pretrain_e20_m0p3"

# 短视界固定60分钟历史，其余预测长度与历史长度相同。
uv run python run_single.py --mode train --model PatchMLPAllFeatures --scenario NoFutureWeather --loss DBLoss --dbloss-weight 0.5 --point-interval-seconds "$POINT_INTERVAL_SECONDS" --window-stride-steps 1 --history-steps 12 --horizon-steps 3 --seed 2026 --pretrain --pretrain-epochs 20 --pretrain-learning-rate 0.001 --pretrain-lr-scheduler cosine_hard_restarts --mae-mask-ratio 0.3 --pretrain-patience 10 --epochs 100 --patience 10 --learning-rate 0.001 --batch-size 32 --num-workers 4 --show-progress 0 --run-dir "$RUN_ROOT/h12_p3_s1_seed2026" --dataset-name "$DATASET_NAME" --result-name patchmlp_all_tokenmask_e20_m0p3_dbloss_5min_h12_p3_s1_seed2026
